const notas = [14, 16, 9, 18, 12];
let soma = 0;

for (const nota of notas) {
  soma += nota;
}

console.log(soma); // 69

const stock = { canetas: 120, cadernos: 45, borrachas: 80 };
let total = 0;

for (const produto in stock) {
  if (Object.hasOwn(stock, produto)) {
    console.log(`${produto}: ${stock[produto]}`);
    total += stock[produto];
  }
}

console.log(`Total em stock: ${total}`);

const carro = { marca: 'Toyota', modelo: 'Corolla', ano: 2023, cor: 'branco' };
const linhas = [];

for (const [chave, valor] of Object.entries(carro)) {
  linhas.push(`${chave}: ${valor}`);
}

console.log(linhas);

const turmas = new Map([
  ['A', [{ nome: 'Rita', nota: 15 }, { nome: 'Tiago', nota: 12 }]],
  ['B', [{ nome: 'Sofia', nota: 18 }, { nome: 'Bruno', nota: 14 }]],
]);

for (const [turma, alunos] of turmas) {
  let soma = 0;

  for (const aluno of alunos) {
    soma += aluno.nota;
  }

  const media = soma / alunos.length;
  console.log(`Turma ${turma}: ${media}`);
}
